// ==== КОНФИГ: какие метрики отслеживаем ====
// direction нужен только для текста алерта (что считать "плохим" отклонением),
// на сам расчёт z-score не влияет — аномалия есть аномалия в любую сторону.
const METRICS = [
  { key: 'Чистый_сон_мин',            label: 'Сон (чистый, мин)',      direction: 'higher_better' },
  { key: 'Эффективность_сна_',        label: 'Эффективность сна',      direction: 'higher_better', isPercent: true },
  { key: 'Оценка_сна_балл',           label: 'Оценка сна',             direction: 'higher_better' },
  { key: 'Пульс_ночной_средний',      label: 'RHR ночной',             direction: 'lower_better' },
  { key: 'Восстановление_BodyBattery',label: 'Восстановление (BB)',    direction: 'higher_better' },
  { key: 'Стресс_дневной_средний',    label: 'Стресс дневной',         direction: 'lower_better' },
  { key: 'VO2_Max',                   label: 'VO2 Max',                direction: 'higher_better' },
  { key: 'Питание_Всего_Ккал',        label: 'Калории',                direction: 'neutral' },
  { key: 'Питание_Всего_Белки_г',     label: 'Белок',                  direction: 'higher_better' },
  { key: 'Шаги_за_вчера',             label: 'Шаги',                   direction: 'neutral' },
  { key: 'ВСР_ночная',                label: 'HRV ночная',             direction: 'higher_better' },
];

const WINDOWS = [
  { days: 7,  minPoints: 4,  label: '7д'  },
  { days: 30, minPoints: 10, label: '30д' },
  { days: 90, minPoints: 20, label: '90д' },
];

const Z_MODERATE = 1.5;
const Z_STRONG   = 2.0;

// ==== ПАРСИНГ ЧИСЕЛ ====
function toNumber(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return v;
  const cleaned = String(v).trim().replace('%', '').replace(',', '.');
  const n = parseFloat(cleaned);
  return isNaN(n) ? null : n;
}

function parseDate(v) {
  if (!v) return null;
  // берём только дату (YYYY-MM-DD), время игнорируем для группировки
  const s = String(v).trim().slice(0, 10);
  const d = new Date(s + 'T00:00:00Z');
  return isNaN(d.getTime()) ? null : d;
}

// ==== СБОР ДАННЫХ ИЗ ВХОДЯЩИХ ITEMS ====
const rawRecords = items
  .map(item => {
    const j = item.json;
    const date = parseDate(j['Дата']);
    if (!date) return null;
    const metrics = {};
    for (const m of METRICS) {
      metrics[m.key] = toNumber(j[m.key]);
    }
    return { date, dateStr: j['Дата'].slice(0, 10), metrics };
  })
  .filter(r => r !== null)
  .sort((a, b) => a.date - b.date);

// ==== СТАТИСТИКА ====
function mean(arr) {
  return arr.reduce((s, v) => s + v, 0) / arr.length;
}
function stdSample(arr, m) {
  if (arr.length < 2) return null;
  const variance = arr.reduce((s, v) => s + (v - m) ** 2, 0) / (arr.length - 1);
  return Math.sqrt(variance);
}

function getBaseline(records, idx, metricKey, windowDays, minPoints) {
  const currentDate = records[idx].date;
  const from = new Date(currentDate);
  from.setUTCDate(from.getUTCDate() - windowDays);

  const values = [];
  for (let i = 0; i < idx; i++) {
    const r = records[i];
    if (r.date >= from && r.date < currentDate) {
      const v = r.metrics[metricKey];
      if (v !== null) values.push(v);
    }
  }
  if (values.length < minPoints) return null;

  const m = mean(values);
  const sd = stdSample(values, m);
  return { mean: m, std: sd, count: values.length };
}

function classify(absZ) {
  if (absZ === null) return null;
  if (absZ >= Z_STRONG) return 'strong';
  if (absZ >= Z_MODERATE) return 'moderate';
  return null;
}

// ==== ОСНОВНОЙ ПРОХОД ====
const output = rawRecords.map((rec, idx) => {
  const metricResults = {};
  const anomalies = [];

  for (const m of METRICS) {
    const value = rec.metrics[m.key];
    if (value === null) continue;

    const windowsResult = {};
    let bestSeverity = null;
    let bestWindowLabel = null;
    let bestZ = null;
    let bestBaseline = null;

    for (const w of WINDOWS) {
      const baseline = getBaseline(rawRecords, idx, m.key, w.days, w.minPoints);
      if (!baseline || !baseline.std || baseline.std === 0) {
        windowsResult[w.label] = null;
        continue;
      }
      const z = (value - baseline.mean) / baseline.std;
      windowsResult[w.label] = {
        z: Number(z.toFixed(2)),
        baseline_mean: Number(baseline.mean.toFixed(2)),
        baseline_std: Number(baseline.std.toFixed(2)),
        n: baseline.count,
      };

      const severity = classify(Math.abs(z));
      // приоритет — 30-дневное окно как основное, но фиксируем самое "сильное" отклонение
      if (severity && (!bestSeverity || (severity === 'strong' && bestSeverity !== 'strong'))) {
        bestSeverity = severity;
        bestWindowLabel = w.label;
        bestZ = z;
        bestBaseline = baseline;
      }
    }

    metricResults[m.key] = { value, windows: windowsResult };

    if (bestSeverity) {
      const worse =
        m.direction === 'higher_better' ? bestZ < 0 :
        m.direction === 'lower_better'  ? bestZ > 0 :
        null; // neutral — направление не оцениваем

      anomalies.push({
        metric: m.key,
        label: m.label,
        value,
        z: Number(bestZ.toFixed(2)),
        window: bestWindowLabel,
        severity: bestSeverity,
        baseline_mean: Number(bestBaseline.mean.toFixed(2)),
        direction: m.direction,
        interpretation: worse === true ? 'ухудшение' : worse === false ? 'улучшение' : 'отклонение',
      });
    }
  }

  return {
    json: {
      date: rec.dateStr,
      metrics: metricResults,
      anomalies,
      hasAnomalies: anomalies.length > 0,
      isLatest: idx === rawRecords.length - 1,
    },
  };
});

return output;

