  return [];
}

return [{ json: latest.json }];

const all = items.map(i => i.json).sort((a, b) => a.date.localeCompare(b.date));

if (all.length === 0) return [];

const lastDate = new Date(all[all.length - 1].date + 'T00:00:00Z');
const weekAgo = new Date(lastDate);
weekAgo.setUTCDate(weekAgo.getUTCDate() - 7);

const weekRecords = all.filter(r => {
  const d = new Date(r.date + 'T00:00:00Z');
  return d > weekAgo && d <= lastDate;
});

return weekRecords.map(r => ({ json: r }));

