const byMetric = {};
for (const a of allAnomalies) {
  if (!byMetric[a.metric]) {
    byMetric[a.metric] = { label: a.label, occurrences: 0, days: [], direction: a.direction };
  }
  byMetric[a.metric].occurrences += 1;
  byMetric[a.metric].days.push(a.date);
}

const metricSummaryLines = Object.values(byMetric).map(m =>
  `${m.label}: аномалия ${m.occurrences}× за неделю (${m.days.join(', ')})`
);

