  type: 'weekly_digest',
  period_start: week[0]?.date,
  period_end: week[week.length - 1]?.date,
  days_with_data: week.length,
  total_anomalies: allAnomalies.length,
  strong_anomalies: allAnomalies.filter(a => a.severity === 'strong').length,
  metric_summary_lines: metricSummaryLines,
  days_detail: week.map(d => ({
    date: d.date,
    anomaly_count: d.anomalies.length,
    anomalies: d.anomalies.map(a => `${a.label} (z=${a.z}, ${a.severity})`),
  })),
};

return [{ json: digestContext }];

const rec = items[0].json;

// Сортируем аномалии: сначала strong, потом moderate
const sorted = [...rec.anomalies].sort((a, b) => {
  const rank = { strong: 0, moderate: 1 };
  return rank[a.severity] - rank[b.severity];
});

