  const arrow = a.z > 0 ? '↑' : '↓';
  const sev = a.severity === 'strong' ? '🔴 сильное' : '🟡 умеренное';
  return `${sev} отклонение — ${a.label}: ${a.value} (${arrow} z=${a.z} за окно ${a.window}, baseline≈${a.baseline_mean}) — ${a.interpretation}`;
});

const alertContext = {
  type: 'anomaly_alert',
  date: rec.date,
  anomaly_count: sorted.length,
  strong_count: sorted.filter(a => a.severity === 'strong').length,
  summary_lines: lines,
  raw_anomalies: sorted, // на случай, если агенту нужны точные числа
};

return [{ json: alertContext }];

